function initialize(){
 const root=document.getElementById('geography'),svg=d3.select(root.querySelector('svg')),controls=root.querySelector('.controls'),stops=[{name:'Seattle',coordinates:[-122.33,47.61]},{name:'San Francisco',coordinates:[-122.42,37.77]},{name:'Los Angeles',coordinates:[-118.24,34.05]}];let selected='Seattle';root.querySelector('.map-source span').textContent=GEO.source;
 function select(name,persist=false){selected=name;const stop=stops.find(s=>s.name===name);root.querySelector('.destination-detail strong').textContent=name;root.querySelector('.destination-detail span').textContent=stop.coordinates[1].toFixed(2)+'° N, '+Math.abs(stop.coordinates[0]).toFixed(2)+'° W';svg.selectAll('.map-point').attr('data-selected',s=>String(s.name===name));controls.querySelectorAll('button').forEach(button=>button.setAttribute('aria-pressed',String(button.textContent===name)));if(persist)Websandbox.connection.remote.setState({state:{selected},modelContext:{destination:name,coordinates:stop.coordinates}})}
 stops.forEach(stop=>{const button=document.createElement('button');button.type='button';button.textContent=stop.name;button.addEventListener('click',()=>select(stop.name,true));controls.append(button)});
 function draw(){const width=Math.max(280,root.clientWidth),height=320,projection=d3.geoMercator().fitExtent([[24,24],[width-70,height-24]],{type:'MultiPoint',coordinates:[[-130,30],[-110,52]]}),path=d3.geoPath(projection);svg.attr('viewBox',[0,0,width,height]);svg.selectAll('*').remove();svg.append('g').selectAll('path').data(GEO.countries.features).join('path').attr('class','land').attr('d',path);svg.append('path').datum({type:'LineString',coordinates:stops.map(s=>s.coordinates)}).attr('class','connection').attr('d',path);const points=svg.append('g').selectAll('g').data(stops).join('g').attr('transform',s=>'translate('+projection(s.coordinates).join(',')+')');points.append('circle').attr('class','map-point').attr('r',5).attr('data-selected',s=>String(s.name===selected));points.append('text').attr('x',10).attr('y',-9).text(s=>s.name)}
 new ResizeObserver(draw).observe(root);draw();select(selected);Websandbox.connection.remote.getState().then(state=>{if(stops.some(s=>s.name===state?.selected))select(state.selected)});
}
